      var pUp = p > 25 ? 0.35 : (p < 3 ? 0.8 : 0.5);
      var up = Math.random() < pUp;
      var mag = Math.max(0.1, p * (0.06 + Math.random() * 0.2));
      var nb = r1(clampP(up ? p + mag : p - mag));
