        (save.cc > 0 ? '<br>Купил в среднем по ' + (Math.round(ccAvg() * 10) / 10).toString().replace('.', ',') + ', итог: <b class="' + (pl >= 0 ? 'up' : 'down') + '">' + (pl >= 0 ? '+' : '−') + Math.abs(Math.round(pl)).toLocaleString('ru-RU') + '</b>' : '');
      phBody.appendChild(hold);
