        for (var q = 0; q < 5; q++) { var rr = wh.r * (0.25 + q * 0.18), ph = t * 5 - q; ctx.beginPath(); ctx.ellipse(0, 0, rr, rr * 0.18, 0, ph, ph + 4.2); ctx.stroke(); }
