        if (s.k === 'mg') { damageBoss(s.dm, true); burst(s.x, s.y, 2, '#ffd23f', 120, 0.25); }
        else if (s.k === 'rkt') { damageBoss(s.dm); ring(s.x, s.y, 60, '#ff9a3c'); burst(s.x, s.y, 14, '#ff9a3c', 320, 0.6); sfx('rare'); }
