      for (i = 0; i < n; i++) beams.push({ kind: 'laser', t: 0, aim: aim, fire: 0.5, dx: i ? (i % 2 ? -1 : 1) * (170 + Math.random() * 90) * (i > 1 ? 1.5 : 1) : 0, hit: false, tx: P.x, gx: P.x, end: null });
      sfx('no');
