      ctx.fillStyle = '#b97a3a'; ctx.beginPath(); ctx.ellipse(0, 1, 5, 6.5, 0, 0, 6.3); ctx.fill();
      ctx.fillStyle = '#5b3d26'; ctx.beginPath(); ctx.arc(0, -3, 5.5, Math.PI, 0); ctx.fill();
