    var g = c.getContext('2d'); g.drawImage(img.rooster, 0, 0);
    g.globalCompositeOperation = 'source-atop'; g.fillStyle = 'rgba(' + sk.c + ',' + sk.a + ')'; g.fillRect(0, 0, c.width, c.height);
