    ctx.beginPath(); ctx.moveTo(x - 14, top + 6); ctx.lineTo(x + 8, top - 26); ctx.lineTo(x + w - 8, top - 26); ctx.lineTo(x + w + 14, top + 6); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#7e1d25'; ctx.fillRect(x - 14, top + 2, w + 28, 8);
    // вывеска
