    for (var tI = 0; tI < 3; tI++) { ctx.beginPath(); ctx.ellipse(x + w + 34, gY - 8 - tI * 14, 20, 8, 0, 0, 6.3); ctx.fill(); }
    ctx.fillStyle = '#555';
    for (var tJ = 0; tJ < 3; tJ++) { ctx.beginPath(); ctx.ellipse(x + w + 34, gY - 8 - tJ * 14, 9, 3.5, 0, 0, 6.3); ctx.fill(); }
    // подпись
