    var ok = !maxed && save.coins >= cost;
    d.innerHTML = '<div class="top"><span class="nm">' + name + '</span><span class="lv">' + (lvText || 'ур. ' + lvl + (maxed ? ' (макс.)' : '')) + '</span></div>' +
      '<div class="ds">' + desc + '</div>';
