  function relHp() { return (save.mx.rel | 0) === 2 ? Math.round(40 * relS()) : 0; }
  function relMag() { var r = save.mx.rel | 0; return r === 1 ? Math.round(80 * relS()) : (r === 3 ? -Math.round(50 * relS()) : 0); }
  function relReg() { return (save.mx.rel | 0) === 1 ? 1 + 0.6 * relS() : 1; }
